/// Client times (client/view.md, 6) and Home's last-look span (3.5).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum TimeForm {
    Ago,
    Looked,
    Span,
    Clock,
    Dated,
    Weekday,
    Day,
}
const MINUTE: u64 = 60_000_000_000;
const DAY: u64 = 86_400_000_000_000;

/// A build accumulates only the times it actually draws.
#[derive(Debug)]
pub(crate) struct Times {
    pub(crate) now: skein_lib::Wall,
    pub(crate) next: Option<skein_lib::Wall>,
}
impl Times {
    pub(crate) fn new(now: skein_lib::Wall) -> Self {
        Self { now, next: None }
    }
    pub(crate) fn model_new(&mut self, model: &jig_client::contract::MeModel) -> bool {
        if model.source != jig_client::contract::ModelSource::List {
            return false;
        }
        let Some(until) = model.new_until else { return false };
        if until <= self.now {
            return false;
        }
        self.next = [self.next, Some(until)].into_iter().flatten().min();
        true
    }
    pub(crate) fn say(&mut self, words: &Words, form: TimeForm, at: skein_lib::Wall) -> Box<[u8]> {
        let (text, next) = words.time(form, at, self.now);
        self.next = [self.next, next].into_iter().flatten().min();
        text
    }
    /// Public rows use full units with the same span, ago and reconsideration rules (client/web/public.md, 3).
    pub(crate) fn public_time(&mut self, words: &Words, form: TimeForm, at: skein_lib::Wall) -> Box<[u8]> {
        let text = self.say(words, form, at);
        let minutes = self.now.as_nanos().saturating_sub(at.as_nanos()).checked_div(MINUTE).expect("nonzero minute");
        match form {
            TimeForm::Span => words.public_span(minutes),
            TimeForm::Ago if minutes > 0 && minutes < 720 => {
                words.say(Word::TimeAgo, &[Hole::Name(words.public_span(minutes))])
            }
            TimeForm::Ago
            | TimeForm::Looked
            | TimeForm::Clock
            | TimeForm::Dated
            | TimeForm::Weekday
            | TimeForm::Day => text,
        }
    }
}
impl Words {
    /// Words and the instant at which to reconsider them. No clock is read here.
    #[must_use]
    pub fn time(
        &self,
        form: TimeForm,
        at: skein_lib::Wall,
        now: skein_lib::Wall,
    ) -> (Box<[u8]>, Option<skein_lib::Wall>) {
        let elapsed = now.as_nanos().saturating_sub(at.as_nanos());
        let minutes = elapsed / MINUTE;
        let unit = match form {
            TimeForm::Ago if minutes < 720 => Some(MINUTE),
            TimeForm::Span | TimeForm::Looked if elapsed < DAY => Some(MINUTE),
            TimeForm::Span | TimeForm::Looked => Some(DAY),
            TimeForm::Ago | TimeForm::Clock | TimeForm::Dated | TimeForm::Day | TimeForm::Weekday => None,
        };
        let next = next_tick(at, now, elapsed, unit, self.zone_minutes);
        let said = match form {
            TimeForm::Looked => self.looked_span(minutes),
            TimeForm::Span => self.time_span(minutes),
            TimeForm::Ago if minutes == 0 => self.say(Word::TimeJustNow, &[]),
            TimeForm::Ago if minutes < 720 => self.say(Word::TimeAgo, &[Hole::Name(self.time_span(minutes))]),
            TimeForm::Ago | TimeForm::Clock | TimeForm::Dated | TimeForm::Day | TimeForm::Weekday => {
                self.calendar_time(form, at, now)
            }
        };
        (said, next)
    }
    fn looked_span(&self, minutes: u64) -> Box<[u8]> {
        match minutes {
            0 | 1 => self.say(Word::LookedMinute, &[]),
            2..60 => self.say(Word::LookedMinutes, &[Hole::Number(minutes)]),
            60..120 => self.say(Word::LookedHour, &[]),
            120..1440 => self.say(Word::LookedHours, &[Hole::Number(minutes / 60)]),
            1440..2880 => self.say(Word::LookedDay, &[]),
            2880..=u64::MAX => self.say(Word::LookedDays, &[Hole::Number(minutes / 1440)]),
        }
    }
    fn public_span(&self, minutes: u64) -> Box<[u8]> {
        if minutes == 0 {
            return self.say(Word::PublicUnderMinute, &[]);
        }
        let remainder = minutes.checked_rem(60).expect("nonzero hour");
        if !(60..1440).contains(&minutes) || remainder == 0 {
            return self.looked_span(minutes);
        }
        let hours = minutes.checked_sub(remainder).expect("whole hours precede minutes");
        self.say(Word::PublicTimeParts, &[Hole::Name(self.looked_span(hours)), Hole::Name(self.looked_span(remainder))])
    }
    /// Whole wake spans use the largest exact unit (client/pages/team.md, 1).
    pub(crate) fn wake_span(&self, span: skein_lib::Duration) -> Box<[u8]> {
        let nanos = span.as_nanos();
        for (unit, one, many) in [
            (604_800_000_000_000, Word::WakeWeek, Word::WakeWeeks),
            (DAY, Word::WakeDay, Word::WakeDays),
            (3_600_000_000_000, Word::WakeHour, Word::WakeHours),
            (MINUTE, Word::WakeMinute, Word::WakeMinutes),
            (1_000_000_000, Word::WakeSecond, Word::WakeSeconds),
        ] {
            if nanos != 0 && nanos.is_multiple_of(unit) {
                let count = nanos.checked_div(unit).expect("wake units are nonzero");
                return if count == 1 { self.say(one, &[]) } else { self.say(many, &[Hole::Number(count)]) };
            }
        }
        self.say(Word::WakeSeconds, &[Hole::Number(nanos.checked_div(1_000_000_000).expect("second is nonzero"))])
    }
    pub(crate) fn wake_weekly(&self, at: skein_lib::Wall) -> Box<[u8]> {
        self.say(
            Word::WakeWeekly,
            &[Hole::Name(self.time_weekday(self.calendar_day(at), true)), Hole::Name(self.turn_clock(at))],
        )
    }
    pub(crate) fn time_span(&self, minutes: u64) -> Box<[u8]> {
        match minutes {
            0 => self.say(Word::TimeUnderMinute, &[]),
            1..60 => self.say(Word::TimeMinutes, &[Hole::Number(minutes)]),
            60..1440 if minutes.is_multiple_of(60) => self.say(Word::TimeHours, &[Hole::Number(minutes / 60)]),
            60..1440 => self.say(Word::TimeHoursMinutes, &[Hole::Number(minutes / 60), Hole::Number(minutes % 60)]),
            _ => self.say(Word::TimeDays, &[Hole::Number(minutes / 1440)]),
        }
    }
    fn calendar_time(&self, form: TimeForm, at: skein_lib::Wall, now: skein_lib::Wall) -> Box<[u8]> {
        let day = self.calendar_day(at);
        let today = self.calendar_day(now);
        let days = today.checked_sub(day);
        let clock = self.turn_clock(at);
        match form {
            TimeForm::Ago if day == today => self.say(Word::TimeAt, &[Hole::Name(clock)]),
            TimeForm::Ago if days == Some(1) => self.say(Word::TimeYesterdayWord, &[]),
            TimeForm::Ago if days >= Some(2) && days <= Some(7) => self.time_weekday(day, false),
            TimeForm::Ago => self.time_date(at, now),
            TimeForm::Dated if day == today => self.say(Word::TimeTodayClock, &[Hole::Name(clock)]),
            TimeForm::Clock if day == today => clock,
            TimeForm::Clock | TimeForm::Dated => {
                let date = if days >= Some(1) && days <= Some(6) {
                    self.time_weekday(day, false)
                } else {
                    self.time_date(at, now)
                };
                self.say(Word::TimePair, &[Hole::Name(date), Hole::Name(clock)])
            }
            TimeForm::Weekday => self.time_weekday(day, true),
            TimeForm::Day => {
                let date = self.say(
                    Word::TimePair,
                    &[Hole::Name(self.time_weekday(day, true)), Hole::Name(self.time_date(at, now))],
                );
                match days {
                    Some(0) => self.say(Word::TimeToday, &[Hole::Name(date)]),
                    Some(1) => self.say(Word::TimeYesterday, &[Hole::Name(date)]),
                    _ => date,
                }
            }
            TimeForm::Span | TimeForm::Looked => unreachable!("spans have no calendar words"),
        }
    }
    /// A turn under a day line has a fixed clock and needs no wake of its own.
    pub(crate) fn turn_clock(&self, at: skein_lib::Wall) -> Box<[u8]> {
        let minute = self.local_nanos(at).div_euclid(i128::from(MINUTE));
        let minute = u64::try_from(minute.rem_euclid(1440)).expect("minute in day");
        self.say(
            Word::TimeClock,
            &[Hole::Name(copy_of(&two_digits((minute / 60) % 24))), Hole::Name(copy_of(&two_digits(minute % 60)))],
        )
    }
    /// A session always names its weekday, including today, in the person's zone.
    pub(crate) fn session_clock(&self, at: skein_lib::Wall) -> Box<[u8]> {
        self.say(
            Word::TimePair,
            &[Hole::Name(self.time_weekday(self.calendar_day(at), false)), Hole::Name(self.turn_clock(at))],
        )
    }
    fn time_weekday(&self, day: i64, full: bool) -> Box<[u8]> {
        let short = [
            Word::TimeSundayShort,
            Word::TimeMondayShort,
            Word::TimeTuesdayShort,
            Word::TimeWednesdayShort,
            Word::TimeThursdayShort,
            Word::TimeFridayShort,
            Word::TimeSaturdayShort,
        ];
        let long = [
            Word::TimeSunday,
            Word::TimeMonday,
            Word::TimeTuesday,
            Word::TimeWednesday,
            Word::TimeThursday,
            Word::TimeFriday,
            Word::TimeSaturday,
        ];
        let index = usize::try_from(day.checked_add(4).expect("epoch day fits").rem_euclid(7)).expect("weekday fits");
        self.say(*if full { long.get(index) } else { short.get(index) }.expect("weekday in week"), &[])
    }
    pub(crate) fn time_date(&self, at: skein_lib::Wall, now: skein_lib::Wall) -> Box<[u8]> {
        let (year, month, day) = civil_date(self.calendar_day(at));
        let months = [
            Word::TimeJanuary,
            Word::TimeFebruary,
            Word::TimeMarch,
            Word::TimeApril,
            Word::TimeMay,
            Word::TimeJune,
            Word::TimeJuly,
            Word::TimeAugust,
            Word::TimeSeptember,
            Word::TimeOctober,
            Word::TimeNovember,
            Word::TimeDecember,
        ];
        let month = months
            .get(usize::try_from(month.checked_sub(1).expect("months start at one")).expect("month fits"))
            .expect("month in year");
        let date = self.say(Word::TimeDate, &[Hole::Number(day), Hole::Name(self.say(*month, &[]))]);
        if year == civil_date(self.calendar_day(now)).0 {
            date
        } else {
            self.say(Word::TimeDateYear, &[Hole::Name(date), Hole::Number(year.unsigned_abs())])
        }
    }
}
#[expect(clippy::arithmetic_side_effects, reason = "each input is below 100; each output is a decimal digit")]
fn two_digits(value: u64) -> [u8; 2] {
    let value = u8::try_from(value).expect("clock field fits");
    [b'0' + value / 10, b'0' + value % 10]
}
// Gregorian civil date; wall nanoseconds and i32 zone minutes bound all intermediates.
#[expect(
    clippy::arithmetic_side_effects,
    reason = "wall nanoseconds and i32 zone minutes bound Gregorian era intermediates within i64"
)]
fn civil_date(day: i64) -> (i64, u64, u64) {
    let days = day + 719_468;
    let era = days.div_euclid(146_097);
    let doe = days.rem_euclid(146_097);
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let day = doy - (153 * mp + 2) / 5 + 1;
    let month = if mp < 10 { mp + 3 } else { mp - 9 };
    (
        era * 400 + yoe + i64::from(month <= 2),
        u64::try_from(month).expect("month is positive"),
        u64::try_from(day).expect("day is positive"),
    )
}

fn next_tick(
    at: skein_lib::Wall,
    now: skein_lib::Wall,
    elapsed: u64,
    unit: Option<u64>,
    zone_minutes: i32,
) -> Option<skein_lib::Wall> {
    let nanos = match unit {
        Some(unit) => {
            let delta = elapsed.checked_div(unit)?.checked_add(1)?.checked_mul(unit)?;
            at.as_nanos().checked_add(delta)?
        }
        None => {
            let offset = i128::from(zone_minutes).checked_mul(i128::from(MINUTE))?;
            let local = i128::from(now.as_nanos()).checked_add(offset)?;
            let midnight = local.div_euclid(i128::from(DAY)).checked_add(1)?.checked_mul(i128::from(DAY))?;
            u64::try_from(midnight.checked_sub(offset)?).ok()?
        }
    };
    Some(skein_lib::Wall::from_nanos(nanos))
}

/// Grouped counts and spend (temper/docs/design/client/pages/accounts.md, 2).
pub(crate) fn grouped(value: u64) -> Box<[u8]> {
    let digits = skein_lib::Decimal::of(value);
    let digits = digits.as_bytes();
    let commas = digits.len().checked_sub(1).expect("decimal has digits").checked_div(3).expect("three is nonzero");
    let mut number = skein_lib::Writer::new(digits.len().checked_add(commas).expect("grouped u64 fits"));
    for (index, digit) in digits.iter().enumerate() {
        if index != 0 && digits.len().checked_sub(index).expect("digit is in decimal").checked_rem(3) == Some(0) {
            number.put(b",").expect("grouped length counted");
        }
        number.put(core::slice::from_ref(digit)).expect("grouped length counted");
    }
    number.finish()
}

